union cypher: member fragments, statemen:
MATCH (n:`RsUser`)
RETURN n { items: [(n)-[:`RS_HAS_ITEM`]->(n0) | n0 { __typename: head([__label IN labels(n0) WHERE __label IN ['RsPost', 'RsDoc', 'RsNote']]), `label`: head(COLLECT { WITH n0 AS this
  RETURN 'p:' + this.title AS v
}) }] }

